// Badge name from data.json ("Migrant", ...) -> 12x12 icon, or nullptr.
static inline const uint8_t* iconForBadge(const char* en) {
  static const char* const names[] = {"Migrant", "Resident", "Raptor", "Nocturnal", "Waterbird", "Rare", "Dawn Caller", "Low confidence"};
  static const uint8_t* const icons[] = {ICON_MIGRANT, ICON_RESIDENT, ICON_RAPTOR, ICON_NOCTURNAL, ICON_WATERBIRD, ICON_RARE, ICON_DAWN_CALLER, ICON_LOW_CONFIDENCE};
  for (int i = 0; i < 8; i++) if (strcmp(en, names[i]) == 0) return icons[i];
  return nullptr;
}
